// 打印
export default function printHtml(html) {
  // let style2 = getStyle2()
  var style = getStyle();
  var container = getContainer(html);
  // document.head.appendChild(style2)
  document.body.appendChild(style);
  document.body.appendChild(container);
  window.print();
  document.body.removeChild(style);
  document.body.removeChild(container);
  // getStyle2.remove()
}
function getStyle() {
  var styleContent = "\n    #print-container{\n      display: none;\n      padding: 20px;\n    }\n   \n    @media print{\n      body > :not(.print-container) {\n        display: none;\n      }\n      html, body{\n        display: block!important;\n      }\n      #print-container{\n        display: block!important;\n      }\n      @page{ margin: 0}\n      \n    }\n  ";
  var style = document.createElement("style");
  style.innerHTML = styleContent;
  return style;
}
